CREATE OR REPLACE FUNCTION create_ghost_user(p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER AS $$$ DECLARE v_id uuid; v_email text; BEGIN v_id := gen_random_uuid(); v_email := 'ghost_' || replace(gen_random_uuid()::text, '-', '') || '@chiprace.com.br'; INSERT INTO auth.users ( id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change ) VALUES ( v_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', v_email, crypt('ghost_pass_' || gen_random_uuid()::text, gen_salt('bf')), now(), now(), now(), '', '', '', '' ); UPDATE public.profiles SET name = p_name WHERE id = v_id; RETURN v_id; END; $$$; GRANT EXECUTE ON FUNCTION create_ghost_user(text) TO authenticated;